  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }
  function hall(id) { return CFG.concerts.filter(function (h) { return h.id === id; })[0]; }

  function renderTree() {
