    setStatus('ok', '✅ <b>' + esc(sel) + '</b> 아래에 회차 <b>' + esc(p.no) + '</b>를 추가했습니다(concert_id가 자동으로 채워짐). View Cluster가 부모 맥락을 이어 줍니다.');
  });

